#!/usr/bin/env bash
set -euo pipefail

# Run from the samples checkout, inside android-emulator-runner's script hook.
diagnostics_dir="$PWD/app/build/ci-diagnostics"
mkdir -p "$diagnostics_dir"
adb_command=(adb -s "${ANDROID_SERIAL:-emulator-5554}")
logcat_pid=

capture() {
    local file="$1" duration="$2" command_status=0
    shift 2
    printf 'Collecting %s\n' "$file"
    timeout --kill-after=5s "$duration" "$@" > "$diagnostics_dir/$file" 2>&1 || command_status=$?
    printf '%s: exit %s\n' "$file" "$command_status" >> "$diagnostics_dir/collection-status.txt"
    # A disconnected device must not replace the original test failure.
    return 0
}

device_state() {
    capture "device-$1.txt" 15s "${adb_command[@]}" shell \
        'getprop; cat /proc/sys/kernel/random/boot_id /proc/uptime; pidof system_server; service check package'
}

print_test_failures() {
    printf '::group::Instrumentation failure traces\n'
    python3 - <<'PY'
from pathlib import Path
import xml.etree.ElementTree as ET

found = False
for path in sorted(Path("app/build/outputs/androidTest-results").rglob("*.xml")):
    try:
        root = ET.parse(path).getroot()
    except (ET.ParseError, OSError) as error:
        print(f"{path}: {error}")
        continue
    for parent in root.iter():
        for problem in parent:
            if problem.tag not in ("failure", "error"):
                continue
            found = True
            name = f"{parent.get('classname', '')}.{parent.get('name', parent.tag)}".lstrip(".")
            print(f"\n{path}: {name}")
            print(problem.get("message", ""))
            print("".join(problem.itertext()).strip() or "No stack trace recorded.")
if not found:
    print("No XML failure traces recorded; inspect logcat and the raw test results artifact.")
PY
    printf '::endgroup::\n'
}

finish() {
    local test_status=$?
    trap - EXIT
    set +e
    printf '%s\n' "$test_status" > "$diagnostics_dir/connected-samples-exit-code.txt"

    if ((test_status != 0)); then
        capture adb-devices.txt 10s adb devices -l
        device_state after
        capture crash-buffer.txt 10s "${adb_command[@]}" logcat -b crash -d -v threadtime '*:V'
        capture last-anr.txt 15s "${adb_command[@]}" shell dumpsys activity lastanr
        capture runner-memory.txt 10s free -h
        capture runner-disk.txt 10s df -h
        capture runner-processes.txt 10s ps -eo pid,ppid,stat,%cpu,%mem,rss,args --sort=-rss
        capture runner-kernel.txt 10s sudo -n dmesg --ctime
    fi

    # Keep the failure tail free of the noise generated by bugreport itself.
    if [[ -n "$logcat_pid" ]]; then
        kill "$logcat_pid" 2>/dev/null
        wait "$logcat_pid" 2>/dev/null
    fi

    if ((test_status != 0)); then
        print_test_failures
        for file in device-before.txt device-after.txt adb-devices.txt crash-buffer.txt last-anr.txt \
            runner-memory.txt runner-disk.txt runner-kernel.txt logcat.txt; do
            printf '::group::%s (last 500 lines; full file in sample-reports)\n' "$file"
            tail -n 500 "$diagnostics_dir/$file"
            printf '::endgroup::\n'
        done

        # These can fail when Android services have died. Retain their errors and
        # partial output; every command is bounded so diagnostics cannot hang CI.
        # Root only after failure collection: restarting adbd interrupts logcat.
        capture adb-root.txt 10s "${adb_command[@]}" root
        capture adb-ready.txt 10s "${adb_command[@]}" wait-for-device
        capture anr-pull.txt 15s "${adb_command[@]}" pull /data/anr "$diagnostics_dir/anr"
        capture tombstones-pull.txt 15s "${adb_command[@]}" pull /data/tombstones "$diagnostics_dir/tombstones"
        while IFS= read -r -d '' file; do
            printf '::group::%s (first 500 lines; full file in sample-reports)\n' "${file#"$diagnostics_dir/"}"
            head -n 500 "$file"
            printf '::endgroup::\n'
        done < <(find "$diagnostics_dir/anr" "$diagnostics_dir/tombstones" -type f ! -name '*.pb' -print0 2>/dev/null)
        capture bugreport.txt 120s "${adb_command[@]}" bugreport "$diagnostics_dir/bugreport.zip"
        printf '::group::Diagnostic collection status\n'
        cat "$diagnostics_dir/collection-status.txt"
        printf '::endgroup::\n'
    fi

    exit "$test_status"
}

trap finish EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# Save all buffers on the host throughout the tests, including system_server and
# native crashes. An app-only filter or a post-failure dump can lose the cause.
"${adb_command[@]}" logcat -b all -v threadtime '*:V' > "$diagnostics_dir/logcat.txt" 2>&1 &
logcat_pid=$!
device_state before

# Leave time for the EXIT trap to collect evidence if the test runner hangs.
timeout --kill-after=30s 15m ./gradlew --continue --console=plain --info --stacktrace \
    -PsdkRepository="$SAMPLES_SDK_REPOSITORY" -PsdkVersion="$SAMPLES_SDK_VERSION" connectedSamples \
    2>&1 | tee "$diagnostics_dir/connected-samples.log"
